{
 "summary": "The R3 theorem is a faithful encoding of Fefferman's alternative (C). For every ν>0 it gives smooth, divergence-free, rapidly decaying initial data u₀ on ℝ³ and a smooth rapidly decaying force f such that no smooth (v,p) on ℝ³×[0,∞) exists with v(·,t)∈L² and uniformly bounded energy. The single most important caveat is in the periodic theorem: it is stated with ∀ u₀ f instead of ∃ u₀ f. It therefore asserts that every pair (u₀,f) is smooth, periodic and divergence-free and admits no solution, which is false (e.g. u₀ = 0, f = 0 is not excluded and has the zero solution). It is not the paper's Corollary 10.6.",
 "glossary": [
  {"decl": "divergence", "line": 81, "plain": "∇·v(x) = trace of the Jacobian Dv(x); equals 0 if v is not differentiable at x", "standard_concept": "divergence of a vector field", "matches_standard": "yes", "note": "The junk value only arises at non-differentiable points; every use is paired with C^∞ hypotheses."},
  {"decl": "IsOnePeriodic", "line": 121, "plain": "f(x+e_i) = f(x) for all x and all coordinate unit vectors e_i", "standard_concept": "ℤ^n-periodic function (function on T^n)", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityCondition", "line": 134, "plain": "u₀ is C^∞ and divergence-free everywhere", "standard_concept": "Fefferman (2) plus smoothness of u°", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityConditionDecay", "line": 150, "plain": "In addition, for all m and K there is C with |∂^m u₀(x)| ≤ C/(1+|x|)^K", "standard_concept": "Fefferman condition (4)", "matches_standard": "yes", "note": "K is real; the base is ≥1, so rpow is well-behaved."},
  {"decl": "InitialVelocityConditionPeriodic", "line": 164, "plain": "Smooth, divergence-free and 1-periodic u₀", "standard_concept": "Fefferman condition (8)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceCondition", "line": 175, "plain": "f is C^∞ on ℝ^n×[0,∞)", "standard_concept": "smooth force", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionDecay", "line": 185, "plain": "All (x,t)-derivatives within ℝ^n×[0,∞) satisfy |∂^m f| ≤ C/(1+|x|+t)^K", "standard_concept": "Fefferman condition (5)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionPeriodic", "line": 200, "plain": "f is smooth, 1-periodic in x for t≥0, and |∂^m f| ≤ C/(1+t)^K", "standard_concept": "Fefferman conditions (8),(9)", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothness", "line": 217, "plain": "(v,p) are C^∞ on ℝ^n×[0,∞) and satisfy: ∂_t v + (v·∇)v = νΔv − ∇p + f (one-sided t-derivative on [0,∞)), ∇·v = 0, and v(x,0) = u₀(x)", "standard_concept": "smooth classical solution of Navier–Stokes", "matches_standard": "yes", "note": "Smoothness rules out junk derivative values."},
  {"decl": "NavierStokesExistenceAndSmoothnessRn", "line": 245, "plain": "Smooth solution with v(·,t) ∈ L² for each t≥0 and sup_t ∫|v|² < E for some E", "standard_concept": "Fefferman (6),(7)", "matches_standard": "yes", "note": "The extra L² requirement only weakens (makes easier) the nonexistence claim."},
  {"decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 262, "plain": "Smooth solution with v and p 1-periodic in x for all t≥0", "standard_concept": "Fefferman (10),(11) with errata", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "navier_stokes_breakdown_R3", "line": 273, "plain": "For every ν>0 there exist u₀: ℝ³→ℝ³ and f: ℝ³×ℝ→ℝ³ such that: u₀ is smooth, divergence-free and Schwartz-decaying; f is smooth on ℝ³×[0,∞) with all derivatives decaying like (1+|x|+t)^{-K}; and there are no smooth (v,p) on ℝ³×[0,∞) solving NS with v(·,t)∈L² and uniformly bounded energy."},
  {"theorem": "navier_stokes_breakdown_periodic", "line": 280, "plain": "For every ν>0 and EVERY u₀, f: u₀ is smooth, periodic and divergence-free; f is smooth, periodic and time-decaying; and no smooth periodic solution exists. This is false as stated."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every ν>0 there are f ∈ C_c^∞(ℝ³×(0,∞)) and u₀ = 0 such that the smooth solution on [0,1) has bounded energy and ‖u(t)‖_∞ → ∞ as t↑1. Hence no smooth bounded-energy global solution exists: alternative (C)."},
  {"ref": "Corollary 10.6", "plain": "For every ν>0 there is a smooth periodic force, compactly supported in time, with zero initial velocity, for which no global smooth periodic solution exists: alternative (D)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1 (consequence, alternative (C))", "lean_theorem": "navier_stokes_breakdown_R3", "relation": "equivalent", "why": "Existential over data satisfying Fefferman's conditions, plus nonexistence of a smooth bounded-energy solution; u₀ = 0 and f ∈ C_c^∞ satisfy the decay conditions."},
  {"paper_ref": "Corollary 10.6", "lean_theorem": "navier_stokes_breakdown_periodic", "relation": "different", "why": "The Lean statement quantifies ∀ u₀ f instead of ∃ u₀ f; that universal claim is false, while the paper claims existence."}
 ],
 "flags": [
  {"id": "F1", "category": "quantifier", "severity": "high", "decl": "navier_stokes_breakdown_periodic", "line": 281, "paper_ref": "Corollary 10.6", "explanation": "The statement uses ∀ (u₀) (f) where alternative (D) and the paper require ∃. As written it claims every function u₀ is smooth, periodic and divergence-free. It also claims that for u₀ = 0, f = 0 no solution exists, but (v,p) = (0,0) is a solution. The statement is false and does not formalize the paper's corollary. It is a different (unprovable) claim, not merely a stronger one.", "polarity": "lean stronger", "probe_idea": "Prove ¬ (∀ ν>0, ∀ u₀ f, InitialVelocityConditionPeriodic u₀ ∧ ...) by instantiating u₀ = fun x => x (not periodic), or u₀ = 0, f = 0 with solution v = 0, p = 0."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "NavierStokesExistenceAndSmoothnessRn", "line": 250, "paper_ref": "Theorem 1.1", "explanation": "The solution class additionally requires v(·,t) ∈ L² for each t. This adds requirements inside ¬∃, so the theorem is slightly weaker than 'no bounded-energy smooth solution'. It is harmless, since bounded energy for a measurable v essentially implies L², and it matches Fefferman (7).", "polarity": "lean weaker", "probe_idea": null}
 ],
 "lint_verdicts": [
  {"line": 81, "rule": "junk-deriv", "verdict": "harmless", "why": "Divergence is only used on fields required to be C^∞, so fderiv is the true derivative."},
  {"line": 155, "rule": "junk-div", "verdict": "harmless", "why": "The denominator (1+‖x‖)^K is positive, so no division by zero occurs."},
  {"line": 155, "rule": "junk-deriv", "verdict": "harmless", "why": "u₀ is C^∞ by the same structure, so iteratedFDeriv is genuine."},
  {"line": 191, "rule": "junk-div", "verdict": "harmless", "why": "1+‖x‖+t ≥ 1 for t ≥ 0, so the denominator is positive."},
  {"line": 205, "rule": "junk-div", "verdict": "harmless", "why": "1+t ≥ 1 for t ≥ 0, so the denominator is positive."},
  {"line": 224, "rule": "nat-sub", "verdict": "harmless", "why": "The subtraction is in ℝ³, not ℕ, so there is no truncation."},
  {"line": 223, "rule": "junk-deriv", "verdict": "harmless", "why": "velocity_smooth gives C^∞ on ℝ³×[0,∞), so the one-sided derivWithin and fderiv are genuine (unique differentiability on Ici 0)."},
  {"line": 253, "rule": "junk-integral", "verdict": "harmless", "why": "The integrable field (MemLp 2) guarantees ‖v‖² is integrable, so the integral is not a junk 0; in a ¬∃ statement a junk value would only weaken the claim anyway."}
 ]
}
